/* Session 2: paraphrased handout + exported classroom transcript. No raw sources shipped. */
let s2Units=[];
const s2Done=()=>read('wset3-session2-completed',[]);
const s2Source=(p,t)=>`<p class="source-note"><span>讲义 p.${p}</span> · <span>课堂转写 ${t}</span></p>`;
function initSession2(){
const part=(title,p,t,body)=>section(title,s2Source(p,t)+body);
const note=(t,p)=>callout('特别注意 · '+t,p);
const extra=(p)=>callout('理解补充',p,true);
const steps=(items)=>`<ol class="s2-steps">${items.map(([t,p])=>`<li><strong>${t}</strong><p>${p}</p></li>`).join('')}</ol>`;
s2Units=[
{id:'training',n:'01',short:'密度与整枝',title:'给葡萄藤，合适的空间',en:'SPACE & STRUCTURE',pages:'24—26',time:'00:00—13:12',duration:12,desc:'先看水分与养分，再选择永久骨架和整枝高度。',body:
part('先分清四个管理概念','24','00:03:33—04:47',table(['术语','管理什么','不要混淆'],[['整枝／整形 Training','建立和维持葡萄藤多年生木的形状，如主干与主蔓','不是单凭芽的数量判断整枝方式'],['修剪 Pruning','去除不需要的叶片、新梢或木质枝条；冬剪常处理一年生木','与整枝有关联，但不是同一个概念'],['搭架 Trellising','用支柱、铁丝等支撑、安排葡萄藤及新梢','头状或主蔓整枝都可能使用架子'],['种植密度 Planting density','单位面积种多少株、株行之间留多少空间','不是每株留多少芽，也不是每公顷产量的同义词']])+'<p>讲义把这些操作共同指向“成熟的葡萄”。作答时要解释每个操作怎样影响光照、通风、植株平衡、作业效率和成本。</p>')+
part('种植密度：不是越密越好','25','00:00—03:33',table(['资源与条件','课堂选择思路','为什么'],[['水分非常有限，或坡面径流导致根区供水不足','可采用较低密度','减少植株之间争水；老师提醒降雨不少也不等于根区水分充足'],['养分偏低但足以生长、降雨充足','可用较高密度形成竞争','限制单株过旺的营养生长，减轻遮阴与通风不足'],['养分与水分都丰富，长势极旺','大树型整枝配合较大株距','给每株更大的永久骨架与冠层空间；不能无限增加密度']])+'<p>老师用欧洲部分葡萄园接近每公顷一万株的高密度，以及新西兰部分肥沃、多雨园地的大树型葡萄藤作说明。这些是课堂情境例子，不是欧洲或新西兰全部葡萄园的标准。</p>'+extra('密度需要结合土壤保水与排水、降雨、灌溉、品种、长势、株行距和机械通行一并决定。课堂的三个情境用于建立分析框架，不是仅凭一项水分或养分指标就能套用的处方。'))+
part('头状与主蔓：看多年生木','25—26','00:06:45—10:44',table(['整枝方式','识别特征','课堂说明'],[['头状 Head training','永久骨架以直立主干及顶部短分叉为主，没有水平延伸的永久主蔓','横着绑的一年生长枝不等于多年生主蔓'],['主蔓 Cordon training','有一个或两个水平延伸的多年生木臂（主蔓）','单主蔓／双主蔓；永久木支撑新梢，可配合机械管理'],['大树型 Big vines','两个以上主蔓，单株占据更大空间','老师用肥沃且降雨充沛的地方举例；大株形意味着不能种得太挤']])+'<p>老师用“只有脑袋”和“长了胳膊”的比喻帮助识别。学习目标是认出形态并说明选择条件；课堂明确不要求把农业操作细节当成机械背诵流程。</p>')+
part('高度：想多受地面影响，还是少受？','26','00:10:44—13:12','<p>头状与主蔓两种方式都可以高干或矮干整形。春季容易发生近地面霜冻时，提高结果部位高度可能降低嫩芽暴露于近地冷空气的风险；需要利用地表蓄热时，较低的结果部位也可能有利。</p><p>老师强调没有绝对最佳高度，要结合气候、地表条件、品种的热量需求与管理方式判断；不能把“欧洲都应高干”或“矮干永远更暖”写成规则。</p>'+flow('具体地点与品种','判断主要风险／需要','选择骨架和高度','解释成熟与成本的后果')),question:'为什么同样是低密度种植，干旱园地与肥沃多雨园地的理由可以完全不同？',answer:'前者可能为减少争水，后者可能为容纳长势旺盛的大树型葡萄藤。相同结果不代表相同原因，要把资源、长势和整枝方式写出来。'},
{id:'pruning',n:'02',short:'冬剪与夏剪',title:'剪掉什么，留下什么',en:'PRUNING & RENEWAL',pages:'26—31',time:'00:13:44—34:32',duration:16,desc:'分清木龄、芽与新梢，再理解短枝和替换长枝。',body:
part('修剪之前，先认清木龄','27—30','00:14:08—17:24、25:34—29:16',table(['结构','怎样理解','与结果的关系'],[['当年新梢 Shoot','生长季从芽长出的绿色枝条，带叶片、花序和果串','果实长在当年的结果新梢上'],['一年生木 Cane','上一个生长季新梢木质化后形成的枝条','其芽可在下一季长出新梢；冬剪决定保留多少、留在哪里'],['多年生木 Permanent wood','保留多年的主干和主蔓等骨架','承担支撑和输导；不能把横向的一年生长枝误认成永久主蔓']])+note('“只有一年生木会长新梢”不要绝对化','课堂为了讲清常规结果结构作了简化。老木也可能由潜伏芽长出新梢；正常产量管理通常围绕一年生木上的结果芽展开。'))+
part('冬剪管潜在负载，夏剪管冠层','26—27','00:13:44—17:24',table(['季节','对象','目的与影响'],[['冬季修剪 Winter pruning','休眠期的木质枝条，主要是一年生木','控制保留芽的数量和位置，影响下一季新梢分布和潜在产量'],['夏季修剪 Summer pruning','当年新梢和叶片','限制多余生长，调整光照、通风、果实暴露及喷药可达性，支持健康与成熟']])+'<p>冬剪不是把“还没长出来的新梢”剪掉，而是处理带芽的枝条；也不等于一定剪除永久骨架。夏剪包含修剪过长的冠层、去除多余新梢、适量摘叶。</p>'+extra('芽多通常意味着更多潜在新梢与果串，但实际产量还受芽的结果力、萌芽率、坐果、天气及病害影响。冬剪重要，却不能单独锁定最终产量。'))+
part('短枝修剪 Spur pruning','28—29','00:18:30—24:10',steps([['将选定的一年生枝剪短','保留短枝（spur）及少量芽，形成下一季新梢的出发点。'],['永久骨架保留','既可配合头状整枝，也可配合主蔓整枝。'],['下一季再更新短枝','芽萌发出新梢，长叶、开花结果，木质化后进入下一轮冬剪。']])+note('讲义与转写留芽数不同','讲义第 28 页（幻灯片 102）写每个短枝 2–3 个芽；转写 19:33 说 1–2 个芽。课本p.52已核对为2–3个芽，本版复习按课本；转写差异仍保留；不能把短枝理解成留一长串芽。')+'<p>课堂将规则化的短枝修剪与较低技术投入、机械预剪潜力联系起来。但是否易于机械修剪，还取决于整枝与搭架形态；不能说所有灌木型短枝葡萄藤都能用同一种机器。</p>')+
part('替换长枝修剪 Replacement cane pruning','29—30','00:24:10—31:41',steps([['去除上一季用过的结果长枝','它已完成结果任务，不让它继续保留成永久水平木臂。'],['选择新的成熟一年生枝','常保留 1 或 2 条长枝；讲义每条为 8–20 芽。课堂视频演示的单居由例子则为最多约 8 芽，属于具体系统。'],['将结果长枝绑到水平铁丝','使芽和下一季新梢分布合理。视频还保留短的更新枝，为下一年提供候选长枝。'],['下一年重复替换','“替换”指新一年的枝条取代已经用过的结果枝，不是把永久主干每年换掉。']])+'<p>选择和绑缚长枝需要判断与熟练人工，通常比规则化机械预剪耗工；但修剪需要人工，不代表之后不能机械采收。部分品种或园地基部芽结果力较低时，长枝修剪可能更适合。</p>'+note('不能用长短直接推算产量高低','老师用“少数长枝”与“许多短枝”解释总留芽量，但短枝／长枝本身并不保证谁高产。应比较整株总留芽、芽的结果力与植株承载能力；同样，基部芽结果力低不等于一定不萌芽。课堂所举黑皮诺及另一个失真品种名不写成全品种通用规则。'))+
part('两个维度，四种组合','31','00:32:16—34:32',table(['多年生骨架 × 冬剪','讲义例子','识别关键'],[['头状 × 长枝','Guyot · 居由式','无永久水平主蔓；一年生结果长枝每年更新'],['主蔓 × 长枝','Sylvoz','永久主蔓上保留长枝；不要因为有长枝就判成头状'],['头状 × 短枝','Bush / Gobelet · 灌木／杯形','头部保留短枝；常见不搭架形态'],['主蔓 × 短枝','Midwire cordon','永久水平木臂上分布短枝']])+'<p>整枝回答“多年生骨架长什么样”，修剪回答“带芽的一年生枝怎么留”。长枝只是被绑成水平，仍然可以是一年生木。</p>'),question:'一株葡萄藤上有一条水平枝，就一定是主蔓整枝吗？',answer:'不一定。需要看水平枝是否为永久多年生木。Guyot 的水平结果长枝通常为一年生木，每年替换，不等同永久主蔓。'},
{id:'canopy',n:'03',short:'搭架与冠层',title:'让光与空气，进入冠层',en:'TRELLISING & CANOPY',pages:'31—32',time:'00:34:32—44:45',duration:11,desc:'遮阴与暴露需要平衡，成本也要分阶段解释。',body:
part('不搭架的灌木型葡萄藤','31','00:35:08—40:11',table(['优势','对应原因'],[['建立成本较低','不需要完整的支柱与铁丝系统，也减少部分绑缚工作'],['可为果实提供遮阴','自然展开的叶幕适合某些炎热、干旱条件，降低过度暴露风险'],['较低、紧凑的树形可适应风大地点','老师强调其稳定性；实际仍取决于结构与风况']])+'<p>缺点是冠层容易拥挤、通风与受光难以精确控制，在凉爽潮湿地点可能增加霉菌风险；灌木型形态通常也不利于常规机械采收。课堂联系西班牙、澳大利亚部分温暖干旱园地，不意味着这些地区全都不搭架。</p>')+
part('搭架与 VSP 不是同义词','31—32','00:40:11—43:46','<p><strong>VSP · Vertical Shoot Positioning（新梢垂直定位／垂直分布）</strong>把新梢安排在向上生长的较窄叶幕中，以铁丝支撑，改善冠层受光、空气流动及管理可达性。既可用于长枝修剪，也可用于短枝修剪；头状或主蔓骨架均能组合。</p><p>凉爽、潮湿且需要更多光照的园地，常能从开放冠层中获益；炎热地区则要防止果实暴露过度。老师举新梢顶部自然下垂、保留更多叶片遮阴的做法，说明“搭架”可以为机械化服务，而不必总是严格的 VSP。</p>'+flow('凉爽／潮湿','适度打开冠层','光照与通风改善','支持成熟、降低霉菌风险')+note('不要过度摘叶','叶片也是制造糖分的器官。保留足够健康叶片、避免果实晒伤，与减少遮阴一样重要；操作强度取决于气候、方位和时机。'))+
part('写成本，要写清是哪一笔','31','00:40:59—41:59',table(['阶段','搭架系统','不搭架灌木系统'],[['建园投入','支柱、铁丝和安装增加投入','可节省部分材料及安装成本'],['生长季管理','绑梢、定位及修整需要人工','减少部分绑缚，但冠层管理仍需劳动'],['采收','合适株行距和树形可支持机械化，提高速度','常规机械采收较难，通常仍需人工']])+'<p>“搭架增加成本”或“不搭架节省成本”都只说了一半。建园、修剪、绑梢与采收是不同账目；当地工价、设备购买或租用和作业规模也影响结果。</p>')+
part('冠层管理 Canopy management 的范围','32','00:43:46—44:45','<p>冠层（叶幕）是当年新梢与叶片形成的空间结构。课堂把新梢定位、搭架配合、修剪枝梢、摘叶与遮阴都纳入冠层管理，目标是在光合作用、果实成熟、病害风险与防晒之间取得平衡。</p>'+table(['操作','想解决的问题','过头的风险'],[['去除多余新梢／修剪冠层','拥挤、互相遮阴、通风差','损失有效叶面积或刺激再生长'],['果区适量摘叶','改善暴露、空气流动与喷药覆盖','晒伤、过热'],['保留遮阴／允许部分新梢下垂','炎热环境中保护果实','遮阴过重可能妨碍成熟、增加潮湿']])) ,question:'为什么不能只写“搭架可以降低成本”？',answer:'搭架通常增加建园和绑梢投入，但在合适地形及树形下可以支持机械采收，降低部分采收人工。必须写清成本发生的阶段和原因。'},
{id:'balance',n:'04',short:'产量与品质',title:'好葡萄，来自平衡',en:'YIELD & VINE BALANCE',pages:'32',time:'00:45:02—54:06',duration:10,desc:'低产不是品质保证，高产也不是自动失败。',body:
part('把“低产一定好”的结论拆开','32','00:45:02—50:20','<p>老师从欧洲部分资源受限的园地解释低产观念：光、热或其他成熟资源不足时，果串过多可能无法充分成熟，因此需要控制负载。但不能把这一步推成全世界都应无限减产。</p><p>在资源充沛的地点，适当较高的果实负载仍可能充分成熟；过低负载未必提升品质，旺盛营养生长还可能带来遮阴。关键是冠层功能、果实负载与可用资源的匹配。</p>'+table(['情境','判断方向'],[['资源有限，结果负载过大','成熟不足、风味不充分的风险上升，可能需要减负载'],['资源充足且冠层健康、负载合适','较高产量也有机会提供成熟、优质果实'],['资源充足却只长枝叶、冠层拥挤','仍需管理长势与结构，不能放任高产或无限施肥'],['单纯把产量降到很低','未必改善品质，还可能减少可售酒量、增加单位成本']]))+
part('风格、价位与法规也进入决策','32','00:50:20—52:51','<p>课堂把产量与预期酒风格、等级、价位及经营目标联系起来：有限资源下，追求更高成熟度和浓缩度可能需要较低负载；另一个价位和风格的酒则未必选择同样目标。</p><p>老师提到欧洲一些产区（如香槟、波尔多）有产量限制。本课保留“法规可能限制产量”这个决策因素，不将模糊转写写成各产区当前法定数值。产区条款待对应章节核对。</p>'+flow('可用资源与品种','目标风格与成熟度','合法且可承受的负载','品质与经营平衡'))+
part('冬剪和摘青，各在什么时候起作用','32','00:52:29—54:06',table(['方法','阶段','课堂解释'],[['冬季修剪','萌芽前','通过留芽数量和位置调整潜在结果负载'],['摘青 Green harvesting','生长季，课堂用转色期前后作说明','去除部分尚未成熟的果串，减少剩余果实之间的竞争']])+'<p>老师提醒摘青时机：过早可能引起补偿性生长，例如剩余果粒增大或长势调整；过晚可能难以明显改善成熟，且先前投入已发生。适当时间与收益仍受品种、年份、目标和成本制约，不应把某一天或某个成熟点当固定答案。</p>'+note('转写校正','52:51—53:54 的“摘星／摘心”结合讲义第 32 页和去掉青葡萄串的描述，整理为“摘青”。摘心是处理新梢尖端，不能与疏除果串混为一谈。')),
question:'如果两块园地产量不同，能直接判断哪块品质更好吗？',answer:'不能。先比较当地资源、品种、冠层和实际成熟度，再看目标风格、果实健康与法规。产量是结果之一，不能单独代替品质评价。'},
{id:'health',n:'05',short:'风险与栽培方式',title:'保护果实，也照顾土地',en:'VINE HEALTH & FARMING',pages:'33—35',time:'00:54:38—1:06:40',duration:15,desc:'病虫害要分类处理，栽培标签不能替代品质判断。',body:
part('天气风险要放回生长阶段','33','讲义补齐；此段转写未逐项覆盖',table(['阶段','讲义列出的风险','联系 Session 1 理解'],[['春季','霜冻、干旱、冰雹、雨、风','嫩芽与新梢受伤；开花坐果可能受干扰'],['夏季','干旱、冰雹、雨、晒伤','叶片功能、供水、果实健康与成熟受影响'],['秋季','雨、冰雹、风','采收窗口和果实健康受威胁'],['冬季','冬季冰冻','多年生木及整株受损，可能需要重植']])+'<p>风险贯穿萌芽、开花坐果、转色、糖分与风味成熟。灾害的时间和强度决定损失，不能只看灾害名称。课堂转写 54:38 直接进入物理屏障，缺少天气风险逐项讲解，因此本节依据讲义补齐。</p>')+
part('虫害：先问伤到哪里','33—34','00:54:38—57:38',table(['对象','怎样伤害葡萄藤或果实','本课防治方向'],[['根瘤蚜 Phylloxera','根系受损，影响植株生长与存活','选择适合的抗性砧木并嫁接；联系 Session 1'],['线虫 Nematodes','土壤中的微小动物，可伤根；部分种类可传播病毒','保持健康种苗，结合园地风险选择材料和管理；VSP 不能解决根区线虫'],['鸟类 Birds','啄破果粒，除直接损失外还增加腐烂入口','在转色、成熟或采收临近时使用防鸟网；需考虑材料与铺设成本'],['哺乳动物 Mammals','取食果实或损坏植株','围栏等物理屏障；老师举野猪、袋鼠'],['昆虫与螨类','取食叶片、损害果实或传播某些病原','识别具体对象再管理；课堂照片还有叶螨，不应把所有对象都称真菌']])+'<p>讲义强调两类后果：降低光合作用能力，或直接损伤、毁坏果实。并非只有果实被整串吃掉才算损失。</p>')+
part('真菌、病毒、细菌：处理逻辑不同','34—35','00:57:38—58:45',table(['类别','讲义／课堂例子','管理思路'],[['讲义归为真菌类病害','霜霉病 Downy mildew、白粉病 Powdery mildew、灰腐 Grey rot','改善冠层通风并使用适当预防或控制措施；可施药不等于任何阶段都能恢复损伤'],['病毒','课堂举卷叶病，叶片卷曲、变色','健康繁殖材料、控制传播媒介及清除感染植株等；不能靠普通杀菌喷雾治好'],['细菌性病害','课堂举皮尔斯病 Pierce’s disease','需针对病害和传播途径管理；课堂以严重感染需拔除说明其难处理']])+extra('霜霉病在葡萄酒教材常与真菌病害一起讨论，病原严格分类属于卵菌。保留讲义分类用于学习，但不把它当生物分类学定义。病毒／细菌的例子也不能扩展成“所有这类病都只有拔除一种办法”。')+'<p>VSP、喷雾、物理屏障、砧木是不同工具。冠层管理能够减少部分病害发生条件，却不能保证不发病，更不能替代所有病虫害控制。</p>')+
part('四种栽培方式：比较投入与限制','35','00:58:45—1:06:40',table(['方式','课堂主线','要保留的条件'],[['常规 Conventional','讲义译“传统”；可使用化肥、杀虫剂、杀菌剂、除草剂等合规投入','老师提醒不等于“用马耕地”；也不能因此推成毫无规则或可以不择手段'],['可持续 Sustainable','关注长期环境与资源，监测风险、减少不必要投入，必要时有针对性使用','课堂举天气预报、湿度监测和预防性喷雾；不等于完全禁用化学投入'],['有机 Organic','限制许多合成肥料与农药，使用获准的方法和投入品','不是绝不喷药，也不是“天然物质皆可用”；课堂天然／合成的例句转写中断，具体许可按认证标准核对'],['生物动力 Biodynamic','以有机原则为基础，并采用特定制剂、农场整体观和相关作业日历等做法','课堂重点讲天体节律及花／果／根／叶日。这是该体系的理念，不能写成已证明能保证酒质的因果']]))+
part('成本与品质：别用标签排座次','35','1:04:30—1:06:40','<p>老师的结论是：有机、生物动力不自动比常规更优质，常规也不等于低品质。限制部分投入后，杂草控制、人工、风险监测和管理的要求可能增加，例如机械除草、翻耕或人工处理。</p><p>因此某些园地可能投入更多劳动或承担更大损失风险，成本与价格可能提高；但高成本不等于高品质，也不代表每一种认证实践在每个环境指标上都必然最佳。应说明具体环境目标和实际措施。</p>'),question:'一张防鸟网、一种杀菌喷雾和一次冠层整理，可以互相替代吗？',answer:'不能。防鸟网针对鸟害，杀菌管理针对特定病原，冠层整理改变光照和湿度条件。先识别威胁及受害部位，再选择合适工具。'},
{id:'harvest',n:'06',short:'采收与贵腐',title:'最后的选择，决定杯中风格',en:'HARVEST DECISIONS',pages:'36—37',time:'1:07:13—1:39:46',duration:18,desc:'时间和方法分开判断；贵腐还涉及逐粒挑选与成本。',body:
part('先选时机，再选方法','36','1:07:13—1:10:56',table(['判断时机的因素','为什么'],[['糖、酸、风味及酚类成熟','糖分决定潜在酒精度，却不能单独代表全部成熟指标'],['品种与地点','早熟或晚熟品种适合的采收窗口不同；转写中的部分品种名待核对'],['目标酒风格','清爽、低酒精度与浓郁饱满的目标可能不同'],['当年天气与果实健康','秋雨或腐烂风险可能迫使提前采收；气候常态与当年预报要分开'],['法规、人员、设备与运输','需在合法和可操作的窗口内把果实送到酒庄']])+'<p>早、中、晚是相对于目标成熟度和当地正常采收窗口而言，不是日历上的全国统一日期。老师谈变暖可能令成熟和采收前移；不能把某产区每一年都必然提前当成结论。</p>')+
part('早采与晚采：都有收益，也有代价','36','1:10:26—1:16:32',table(['选择','想要的效果','需要防范'],[['早采','保留酸度和新鲜感；较低糖分带来较低潜在酒精度','过早可能青生、风味不足，红葡萄还要注意单宁成熟'],['正常采收','在目标风格下取得糖、酸、风味和健康的平衡','正常不是所有品种或酒风格都相同的成熟点'],['晚采','更成熟、浓郁甚至干果风味；潜在酒精度可能更高、酒体更丰满','酸流失、失去新鲜感、过高酒精或天气／病害风险']])+'<p><strong>晚采不等于甜酒。</strong>是否甜取决于葡萄原料与后续发酵等决定；充分发酵的晚采原料也能酿干型酒。葡萄藤上进一步脱水，与采下后再风干是两个过程。</p>')+
part('把老师举的例子保留下来','36','1:11:22—1:16:32',table(['课堂例子','本课要记住什么'],[['Hunter Valley Sémillon · 猎人谷赛美蓉','老师重点：较早采收可塑造清爽、高酸、较低酒精度的干型风格；课堂举约 10–11%，不是所有酒的固定度数'],['意大利部分 Pinot Grigio · 灰皮诺','以较早采收联系简单、易饮、清爽的风格，不外推为意大利全部灰皮诺'],['Vinho Verde · 葡萄牙绿酒','课堂认可的早采风格联系；产区与具体酒款仍需分别判断'],['Beaujolais Nouveau · 博若莱新酒','老师提醒“新酒上市早”不等于风格必然由提前采收造成'],['Amarone · 阿玛罗尼','课堂纠正：采后室内风干，不能只因浓缩或干果味就归作晚采'],['德国特定晚采类别、阿尔萨斯晚采、Jurançon 朱朗松、白诗南、Tokaj 托卡伊','老师以这些联系晚采的不同风格；不要笼统写“所有德国雷司令”或“所有白诗南都晚采”']])+'<p>转写中的“塞北龙”“阿波罗尼”等按明确上下文整理为赛美蓉和阿玛罗尼。德国类别及阿尔萨斯专名在转写中失真，原议题保留在收录核对中，未将音近词直接当作法定名称。</p>')+
part('贵腐 Noble rot：条件、浓缩和选择','37','1:16:32—1:21:28',steps([['先有适合感染的成熟葡萄与环境','Botrytis cinerea 也可造成有害灰腐。潮湿、多雾早晨促进感染，温暖晴朗、干燥下午有助果实失水、限制破坏性腐烂。'],['失水带来浓缩与风味变化','真菌作用提高果皮通透性，水分散失使糖分和某些风味成分浓缩，并产生贵腐相关风味；不是单纯挂得更久。'],['感染和发展并不整齐','一串中可能只有部分果粒适合采收，需要熟练工人多次进园挑选。'],['解释为什么成本高','人工逐粒或局部挑选、数次进园、较长采收窗口、失水后出汁减少，以及天气失败风险共同增加成本。']])+note('“腐而不烂”是课堂记忆提示','老师用这句话形容贵腐与破坏性腐烂的区别；不能理解成果皮完全无损，或只要人工“控制好”就能在任何环境产生贵腐。持续潮湿可能导致灰腐，冠层管理也不能替代合适天气。')+'<p>讲义写贵腐浓缩糖、酸与风味，课堂沿用这个解释。需要保留条件：失水有浓缩作用，但感染过程也能消耗或改变部分成分，不能保证最终酸度在任何情形都上升。贵腐发生时间也随产区、年份变化，不固定为某个全球日期。</p><p>课堂例子有 Sauternes 苏代、德国 BA／TBA、Tokaji Aszú、阿尔萨斯相关贵腐类别及澳大利亚 Riverina；原文失真的类别名称与产区规则另列待核对。</p>')+
part('“每粒都要贵腐吗？”保留问答，暂缓法规结论','37','1:21:28—1:23:05','<p>同学问 TBA 是否必须每粒都感染贵腐。老师先提法律要求，随后又自我修正，把重点转到采收糖度与类别要求，并与 Tokaji Aszú、苏代和 d’Yquem 的选果作比较。</p><p>本次保留“不同酒的原料、糖度及选果要求不能混为一谈”这条主线。关于 TBA、托卡伊是否准用风干葡萄，以及某酒庄是否每次 100% 使用感染果粒等具体说法，<strong>尚未核对相应法规或酒庄资料，不作为已确认规则</strong>；不会为了简短而把这段问答删除。</p>')+
part('人工还是机械：按条件作选择','37','1:23:26—1:30:12',table(['比较','机械采收 Machine harvest','人工采收 Hand harvest'],[['速度与窗口','速度快，可夜间作业，雨前抢收或大面积短窗口中有优势','较慢，取决于劳动力与组织；可灵活分批'],['地形与系统','需要可通行地形、株行距和适合的树形','适合机器难进入的陡坡、某些密植或灌木系统'],['选择性与整串','常规振动式机器主要收果粒；整串需求受限制，仍可能带入梗叶杂质','可以园内挑选成熟度、感染情况，保留整串'],['成本','购机贵，是否低成本取决于购买／租用、规模和当地工资','人工成本可能高；课堂提醒有些地方与机械成本差别未必很大'],['果实完整与运输','果粒可能破损，需迅速运输和处理，控制氧化、微生物与不期望发酵','小筐和仔细操作可保护果实，但也需及时、适温运输']])+'<p>课堂机器视频展示：跨行机器通过振动使果粒脱落，再用输送、分离系统处理部分梗叶；不是把每串整齐剪下。老师提到速度可达人工十几倍，是视频场景的比较，不作为所有机器和园地的性能参数。</p><p>贵腐逐粒分选、需要整串的酿造风格（课堂举香槟和博若莱）通常有人工采收的理由；需要快速、凉夜采收且地形可机械化时，机械可能更合适。课堂最后疑似“默克尔雷司令”的产区名不清，未建立错误对应。</p>'+note('品质不能由采收方式单独判定','讲义和老师都强调两种方式均能酿优质酒。机械采后还可分选，人工采收也可能用于普通酒。清爽风格需要快速低温处理，不等于人工本身一定导致氧化。'))+
part('课末视频：把全年管理连起来','24—37','1:30:44—1:39:10',table(['视频主题','可辨认的内容'],[['选择材料','土壤与砧木不匹配可能出现黄化；品种选择受环境、传统和部分地区法规影响'],['繁殖与建园','扦插和品系选择，抗性砧木嫁接，蜡保护嫁接点，温室／苗圃培育后种入园地；存在自根老藤例外'],['冬季','去除或处理死亡木、修剪、绑缚；单 Guyot 演示保留一条结果长枝和一条更新短枝'],['春夏','萌芽、新梢、花和果实；叶片光合作用，合理叶幕受光与冠层修整'],['生长季保护','潮湿引发腐烂风险；用天气站和监测减少不必要的例行喷雾'],['成熟与采收','在园内不同位置取样，分析糖与酸；炎热环境凉夜采收，减少运输前不期望发酵'],['采收方法','机械速度与地形限制，人工灵活选果，小筐运输；贵腐可多次进园，视频举五次或更多']])+'<p>英文视频转写断裂较多，保留这些可辨认主题。未恢复不清的品种、老藤地点、苗圃规模与年限；视频里把果粉与天然酵母相连的简化句也没有写成“果粉就是酵母”的定义。</p>'),question:'为什么贵腐酒常需要多次人工采收？',answer:'感染与适宜采摘程度不均匀，需熟练工人挑选合适果粒，并反复进园。不能一次机械采完；多次人工、低出汁量与天气风险共同推高成本。'}
];
}
const s2Checks=[
{q:'一条水平绑缚的结果长枝，为什么不一定是主蔓？',o:['所有水平枝都叫主蔓','它可能是一年生木，每年替换','主蔓只能向上生长'],a:1,e:'主蔓是永久多年生木臂。判断头状还是主蔓整枝，要看木龄和永久骨架。',id:'pruning'},
{q:'冬季修剪最直接控制的是什么？',o:['保留芽的数量与位置','葡萄酒最终甜度','当年的所有病害'],a:0,e:'留芽影响下一季潜在新梢与产量；最终结果仍受萌芽、坐果、天气等因素影响。',id:'pruning'},
{q:'炎热环境中冠层管理应特别留意什么？',o:['把果区叶片全摘光','平衡有效叶面积、遮阴与通风','只要搭架就不怕晒伤'],a:1,e:'开放冠层并非越薄越好，果实暴露过度会增加晒伤与过热风险。',id:'canopy'},
{q:'不搭架省成本，这句话怎样写才完整？',o:['任何阶段都更便宜','可降低部分建园与绑缚投入，但采收可能仍需人工','一定能机械采收'],a:1,e:'把建园、绑梢、修剪、采收的成本分开，再结合当地条件判断。',id:'canopy'},
{q:'高产量能否与优质果实并存？',o:['绝对不可能','只要高产就一定好','在资源、冠层与负载匹配时有可能'],a:2,e:'品质不能由产量单项判定，植株平衡、成熟度与目标风格更关键。',id:'balance'},
{q:'有机栽培意味着什么？',o:['任何天然喷剂都能用','无需控制病害','限制特定合成投入，具体许可按认证标准'],a:2,e:'有机不等于不喷药，也不自动保证酒质。',id:'health'},
{q:'贵腐采收为什么昂贵？',o:['只因葡萄名字里有“贵”','感染不均、反复人工挑选且出汁量低、风险高','所有果粒同时成熟，可一次机械采完'],a:1,e:'写出劳动、次数、数量和风险的因果链，比只写“成本高”更有效。',id:'harvest'},
{q:'晚采收一定酿成甜酒吗？',o:['不一定，还要看原料与后续发酵','一定，时间晚就甜','一定只能酿红酒'],a:0,e:'晚采影响成熟、浓度及潜在酒精度；残糖还取决于之后的酿造。',id:'harvest'}
];
function s2Overview(){const done=s2Done();return `<main id="main" class="wrap s2-home"><a class="back" href="#home">← 返回学习期刊</a><section class="s2-hero"><div><div class="issue-label"><b>ISSUE 02</b><span>2026.10.18 · 第二堂课</span></div><div class="eyebrow">THE GROWER'S CHOICES</div><h1 class="two-line-title"><span>管理一座葡萄园，</span><span>也是管理每个选择。</span></h1><p class="intro">从留下一颗芽，到决定采收的一天。<br>把管理选择，连接到成熟、品质与成本。</p><div class="hero-actions"><a class="primary" href="#session2/${s2Units.find(u=>!done.includes(u.id))?.id||'training'}">${done.length?'继续阅读':'开始 Session 2'} ↗</a><a class="text-link" href="#session2quiz">本课自测 →</a><a class="text-link" href="#workbook/2">本课练习册 →</a></div><p class="fine">讲义 p.24—37 · 课本 p.47—61 · 课堂转写约 1 小时 40 分钟</p></div><figure><img src="assets/session2-management.webp" alt="插画：戴手套的双手在铁丝架旁检查冬季枝条，另一侧为夏季葡萄冠层" fetchpriority="high"><figcaption class="art-caption">FIELD NOTES / SESSION 2 · 从条件出发，解释选择。</figcaption></figure></section><div class="session-strip"><strong>葡萄园管理 · 已读 ${done.length} / 6</strong><a href="#session2sources">逐页收录、转写差异与待核对 ↗</a></div><div class="s2-unit-grid">${s2Units.map(u=>`<a class="s2-unit" href="#session2/${u.id}"><span class="s2-num">${u.n}</span><div class="eyebrow">${u.en}</div><h2>${u.short}</h2><p>${u.desc}</p><small>讲义 p.${u.pages} · 约 ${u.duration} 分钟 ${done.includes(u.id)?'✓ 已读':'↗'}</small></a>`).join('')}</div><aside class="editor-note"><div><div class="eyebrow">A NOTE FROM 小 P</div><h3 class="two-line-title"><span>先说条件，</span><span>再解释选择。</span></h3></div><p>这堂课反复提醒：<strong>没有脱离地点与风格的最佳方法。</strong>低产、人工采收、有机栽培都不是品质保证。练习写清“在这样的条件下，采取什么操作，怎样改变成熟、风险或成本”。</p></aside></main>`}
function s2View(id){if(!id)return s2Overview();const u=s2Units.find(x=>x.id===id);if(!u)return `<main id="main" class="wrap"><h1>未找到本课单元</h1><a href="#session2">返回 Session 2</a></main>`;const done=s2Done(),next=s2Units[s2Units.indexOf(u)+1];return `<main id="main" class="lesson-shell"><aside class="lesson-rail"><a class="back" href="#session2">← Session 2 目录</a><div class="eyebrow">SESSION 2 · CONTENTS</div><p class="rail-title">葡萄园管理</p><nav class="rail-list" aria-label="Session 2 单元">${s2Units.map(x=>`<a href="#session2/${x.id}" class="${x.id===u.id?'active':''}" ${x.id===u.id?'aria-current="page"':''}><span>${x.n}</span>${x.short}<i>${done.includes(x.id)?'✓':''}</i></a>`).join('')}</nav><a class="rail-guide" href="#session2sources">来源核对与待确认 ↗</a><a class="rail-guide" href="#workbook/2">Session 2 练习册 ↗</a><a class="rail-guide" href="#session2quiz">Session 2 自测 ↗</a></aside><article class="lesson-content"><div class="eyebrow">SESSION 2 / ${u.en}</div><h1>${u.title}</h1><p class="lesson-deck">${u.desc}</p><div class="source-meta"><span>讲义 p.${u.pages}</span><span>转写 ${u.time}</span><span>约 ${u.duration} 分钟</span></div>${u.body}<details class="recall"><summary>停下来想一想 · ${u.question}</summary><p>${u.answer}</p></details><div class="notes"><label for="s2-note-${u.id}">我的随手笔记 <small id="note-status">仅保存在当前浏览器</small></label><textarea id="s2-note-${u.id}" data-note="session2-${u.id}" placeholder="把条件、操作和结果连成一句完整的解释。">${safe(read(notesKey('session2-'+u.id),''))}</textarea></div><div class="lesson-end"><button class="complete-btn ${done.includes(u.id)?'done':''}" data-s2complete="${u.id}">${done.includes(u.id)?'✓ 已完成阅读':'○ 标记本章已读'}</button><a class="next-link" href="${next?'#session2/'+next.id:'#session2quiz'}">${next?'下一章 · '+next.short:'进入本课自测'} →</a></div></article></main>`}
function s2Quiz(){const ans=read('wset3-session2-answers',{});return `<main class="wrap s2-quiz" id="main"><a class="back" href="#session2">← Session 2 目录</a><div class="eyebrow">PAUSE & RECALL / SESSION 2</div><h1>把每个选择，讲出原因。</h1><p>8 道自编小测 · 不是真题，不代表官方评分标准。已答 ${Object.keys(ans).length} / 8</p><p class="wb-entry"><a class="primary" href="#workbook/2">打开 Session 2 练习册 ↗</a></p>${s2Checks.map((q,i)=>`<section class="quiz-card"><div class="eyebrow">QUESTION ${i+1} / 8</div><h2>${q.q}</h2>${q.o.map((o,j)=>`<button class="option ${ans[i]!==undefined?(j===q.a?'correct':ans[i]===j?'wrong':''):''}" data-s2choice="${i}" data-s2answer="${j}" ${ans[i]!==undefined?'disabled':''}>${String.fromCharCode(65+j)} · ${o}</button>`).join('')}${ans[i]!==undefined?`<div class="callout ${ans[i]===q.a?'green':''}"><strong>${ans[i]===q.a?'答对了':'再看一下原因'}</strong><p>${q.e} <a href="#session2/${q.id}">回看对应单元 ↗</a></p></div>`:''}</section>`).join('')}<section class="quiz-card"><h2>解释练习：凉爽潮湿、人工成本较高的园地，该怎样考虑搭架？</h2><textarea class="short-answer" data-note="session2-practice" aria-label="Session 2 解释练习">${safe(read(notesKey('session2-practice'),''))}</textarea><details class="recall"><summary>检查自己的因果链</summary><p>先讨论冠层受光和通风需求，再讨论支柱与绑梢投入；若地形、行距与树形适合机械作业，可讨论节省采收劳动。不能忽略坡度和整串需求，也不能简单宣布搭架总成本更低。</p></details></section><button class="complete-btn" id="s2-reset">重新开始本课小测 ↻</button><p class="fine">阅读、笔记及答题记录保存在当前浏览器，Session 1 与 Session 2 分开记录。</p></main>`}
function s2Sources(){const links=(id,t)=>`<a href="#session2/${id}">${t} ↗</a>`;return `<main id="main" class="wrap"><article class="guide-content"><a class="back" href="#session2">← 返回 Session 2</a><div class="eyebrow">SOURCE RECONCILIATION / SESSION 2</div><h1>每个知识点，保留来处。</h1><p class="lesson-deck">讲义第 24—37 页（幻灯片 85—140）与 10 月 18 日导出的约 1 小时 40 分钟转写。尚未获得可回听的原始音频，不能声称已逐句听校。</p>${textbookIndex(2)}${section('怎样收录','<p>按知识主题重新组织，保留课堂新增的原因、例子、问答、比较和成本条件。语气重复、点名、休息互动与混入的服装销售声音未纳入知识正文；不清楚但涉及课程的片段单列待核对，不当作无关内容丢弃。讲义原图、原始文档和完整转写不公开上传。</p><p>“理解补充”用于说明适用条件与纠正绝对表述，不伪装成老师原话。以下索引是收录范围核对，不等于原始录音已完整且无误。</p>')}${section('14 页讲义逐页核对',table(['讲义页／幻灯片','收录内容','网页位置'],[
['24 / 85—88','管理导入、整枝／修剪／搭架／密度定义',links('training','密度与整枝')],['25 / 89—92','三种资源情境、种植密度、头状整枝',links('training','密度与整枝')],['26 / 93—96','主蔓、大树型、高矮干与年周期',links('training','骨架和高度')+'；'+links('pruning','冬夏作业')],['27 / 97—100','修剪目的、冬夏对象、修整冠层和摘叶',links('pruning','冬剪与夏剪')],['28 / 101—104','短枝与替换长枝、留芽数字、木龄与步骤',links('pruning','两类冬剪')],['29 / 105—108','主蔓短枝、头状短枝、替换长枝与人工要求',links('pruning','两类冬剪')],['30 / 109—112','替换长枝分步、绑缚、木质结构',links('pruning','替换与木龄')],['31 / 113—116','四种组合、不搭架／搭架与VSP',links('pruning','组合表')+'；'+links('canopy','搭架与冠层')],['32 / 117—120','冠层管理、资源与产量品质、摘青',links('canopy','冠层操作')+'；'+links('balance','产量与品质')],['33 / 121—124','天气风险、生长阶段、虫害后果与控制工具',links('health','风险与工具')],['34 / 125—128','根瘤蚜、线虫、鸟兽、昆虫与真菌类病害',links('health','病虫害分类')],['35 / 129—132','其他病害、四种栽培理念与比较',links('health','栽培方式')],['36 / 133—136','采收时间／方法、早采与晚采',links('harvest','采收时机')],['37 / 137—140','贵腐、人工与机械方法、地形整串与成本',links('harvest','贵腐与采收比较')]
]))}${section('课堂独有内容与视频','<p>00:00—13:12：密度理由、坡地资源损失、大树型和高度；13:44—34:32：木龄、短枝／长枝过程、基部芽和机械化差异；34:32—44:45：不搭架利弊、阶段成本和非严格VSP；45:02—54:06：资源负载平衡、风格价格、摘青时机；54:38—1:06:40：防鸟成本、病虫害工具、常规译法与监测、有机和生物动力；1:07:13—1:30:12：采收例子、贵腐问答、机器视频与完整性；1:30:44—1:39:10：全年管理英文视频；末尾复习提示也已收录。</p><p>转写起点已经在讨论密度，未覆盖完整开场；54:06—54:38 内容有跳接。没有据此编造不存在的课堂讲解。老师建议复习本课，下节进入酿造；讲义首页提示对应课本第 6 章，本次已补入课本p.47—61，见上方逐页索引。</p>')}${section('仍需回听／教材核对',table(['位置','问题','处理方式'],[['开头及54:06—54:38','开场和天气风险段落不完整','讲义内容补齐，未推定缺失音频原句'],['19:33 / 讲义p.28','短枝1–2芽与2–3芽不一致','课本p.52已确认本版复习口径为2–3芽；课堂1–2芽保留作来源差异'],['23:16—24:10、29:36—31:41','修剪方式与产量、品种基部芽的简化结论','保留老师观点并注明总留芽与结果力条件；不清品种名待回听'],['1:02附近','有机允许投入的举例被销售声音打断','课本p.58补入硫与波尔多液用于不同病害；不据此声称听清被遮盖的老师原句'],['1:08:51—1:09:09','早晚熟品种名单多处失真','保留可辨赤霞珠，其余名单待音频'],['1:11:50—1:12:13','被否定的另一个早采例子不清','保留不能用凉爽气候风格直接证明早采的概念，不猜专名'],['1:15:37—1:16:13、1:20:42','德国／阿尔萨斯类别名失真、白石兰等译名','明确者对应白诗南；类别精确拼写、适用规则待教材'],['1:21:47—1:23:05','TBA、Tokaji Aszú、苏代及d’Yquem原料与法律说法','整段议题保留；老师有自我修正，法规及酒庄绝对说法未作定论'],['1:29:52','某产区雷司令机械采收例子不清','不猜产区名'],['1:30:44—1:39:10','英文视频多处断裂','可辨主题收录；老藤地点、品种、苗圃数量年限与果粉简化句待校对']]))}${section('理解补充的核对资料','<p><a href="https://www.awri.com.au/industry_support/viticulture/vineyard-practices/canopy-management-vine-balance-and-vine-pruning/" target="_blank" rel="noopener">AWRI · 冠层、植株平衡与修剪 ↗</a></p><p><a href="https://extension.uga.edu/publications/detail.html?number=B1505&title=dormant-spur-and-cane-pruning-bunch-grapevines" target="_blank" rel="noopener">University of Georgia · 短枝与长枝修剪及芽结果力 ↗</a></p><p><a href="https://www.wsetglobal.com/media/13022/wset_l2wines_sessionplans_en_may2023_issue2.pdf" target="_blank" rel="noopener">WSET · 贵腐与成熟葡萄的官方基础教学资料 ↗</a></p><p class="fine"><a href="https://ipm.ucanr.edu/agriculture/grape/pierces-disease/" target="_blank" rel="noopener">UC IPM · 皮尔斯病管理</a>；<a href="https://www.wsetglobal.com/knowledge-centre/blog/2023/january/13/what-is-natural-wine/" target="_blank" rel="noopener">WSET · 有机与生物动力的相关说明</a>；<a href="https://www.awri.com.au/industry_support/viticulture/pests-and-diseases/botrytis/" target="_blank" rel="noopener">AWRI · Botrytis</a>。以上帮助核对概念，不替代本课所用官方三级教材；未据此宣布通过所有原始录音核查。Session 2 自测为自编练习。</p>')}</article></main>`}
function bindSession2(){document.querySelectorAll('[data-s2complete]').forEach(b=>b.addEventListener('click',()=>{const a=s2Done(),id=b.dataset.s2complete;save('wset3-session2-completed',a.includes(id)?a.filter(x=>x!==id):[...a,id]);const y=window.scrollY;render();window.scrollTo(0,y)}));document.querySelectorAll('[data-s2choice]').forEach(b=>b.addEventListener('click',()=>{const a=read('wset3-session2-answers',{});a[b.dataset.s2choice]=Number(b.dataset.s2answer);save('wset3-session2-answers',a);const y=window.scrollY;render();window.scrollTo(0,y)}));document.querySelector('#s2-reset')?.addEventListener('click',()=>{save('wset3-session2-answers',{});render()})}
